def recall_at_k(retrieved: list[str], relevant: set[str], k: int) -> float:
    return len(set(retrieved[:k]) & relevant) / len(relevant)

def reciprocal_rank(retrieved: list[str], relevant: set[str]) -> float:
    for rank, doc_id in enumerate(retrieved, start=1):
        if doc_id in relevant:
            return 1.0 / rank
    return 0.0  # never found

def evaluate(eval_set: list[dict], search, k: int = 10) -> dict:
    # No-answer items (empty relevant_doc_ids) are scored on abstention instead
    answerable = [ex for ex in eval_set if ex["relevant_doc_ids"]]
    recall, rr, hits = 0.0, 0.0, 0.0
    for ex in answerable:
        rel = set(ex["relevant_doc_ids"])
        # Collapse chunk hits to doc ids, keeping rank order: labels survive re-chunking
        retrieved = list(dict.fromkeys(c.doc_id for c in search(ex["question"], k=k)))
        recall += recall_at_k(retrieved, rel, k)
        rr += reciprocal_rank(retrieved, rel)
        hits += float(bool(rel & set(retrieved[:k])))
    n = len(answerable)
    return {f"recall@{k}": recall / n, "mrr": rr / n, f"hit_rate@{k}": hits / n}

